      distance: 8.2,
      elevation: 514,
      hours: '2.5–3',
      routeShape: 'loop',
      routeShapeNote: 'A loop from Katharinaberg by Durst and the Versanthöfe, a stretch of the Sonnenberg road, Kopfron, Wand and Unterperfl, back to the village.',
      curated: true,
